}

.row-meta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  white-space: nowrap;
  font-size: 0.72rem;
  color: var(--text-secondary);
}

.row-time {
  min-width: 3.5rem;
  text-align: right;
}

.row-pending {
  font-style: italic;
  color: var(--warning);
}

.row-read-state {
  font-size: 0.7rem;
}

