 if(await js("document.querySelector('.app')?.getAttribute('data-client-mode')")!=='browser-preview')throw Error('Not synthetic');
 await js(`(async()=>{const vue=performance.getEntriesByType('resource').map(x=>x.name).find(x=>x.includes('/deps/vue.js?'));const{createApp}=await import(vue);const{default:App}=await import('/src/App.vue');const{createBrowserFakeMailClient}=await import('/src/lib/ipc/browser-fake.ts');window.mountKeysProbe=(gmail=true)=>{window.keysFake?.controls.release();const root=document.querySelector('#app');root.__vue_app__?.unmount();document.documentElement.style.fontSize='16px';const f=createBrowserFakeMailClient();window.keysFake=f;window.keysCalls={save:0,archive:0};if(gmail)f.controls.setAccount({mode:'gmail',connection:'connected',emailAddress:'keys@example.test',mutationAccess:'enabled',coverageLimit:100});const client={...f,saveDraft:c=>{window.keysCalls.save++;return f.saveDraft(c);},setArchived:c=>{window.keysCalls.archive++;return f.setArchived(c);}};createApp(App,{client,mode:'browser-preview'}).mount(root);};})()`);
 await js('window.mountKeysProbe(true)');await tick();await resize(1000);
 await click('[data-test="rail-activity"]');await js("document.querySelector('[data-test=drawer-close]').focus()");
 await key('Tab',true);
 results.hiddenActionBeforeEnter=await js("(()=>{const e=document.activeElement,r=e.getBoundingClientRect(),d=document.querySelector('[data-test=utility-drawer]'),dr=d.getBoundingClientRect(),hit=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);return{activeTest:e.getAttribute('data-test'),activeTag:e.tagName,rect:{left:r.left,right:r.right,top:r.top,bottom:r.bottom},overlay:{left:dr.left,right:dr.right,top:dr.top,bottom:dr.bottom},hitTest:hit?.getAttribute('data-test'),hitTag:hit?.tagName,hitIsFocused:hit===e,operationCount:window.keysFake.controls.activity().length,drawer:!!d};})()");
 await key('Enter');results.hiddenActionAfterEnter=await js("({drawer:!!document.querySelector('[data-test=utility-drawer]'),activeTest:document.activeElement.getAttribute('data-test'),calls:{...window.keysCalls},operations:window.keysFake.controls.activity().map(o=>({kind:o.kind,conversation:o.conversation.conversationId,archived:o.requestedArchived,status:o.status}))})");
 await js('window.mountKeysProbe(true)');await tick();await click('[data-test="rail-drafts"]');await click('[data-test="new-draft"]');
 await js("(()=>{const e=document.querySelector('[data-test=draft-body]');e.value='Synthetic Escape draft';e.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('[data-test=drawer-close]').focus();})()");await tick();
 const draft=()=>js("({drawer:!!document.querySelector('[data-test=utility-drawer]'),composer:!!document.querySelector('[data-test=composer]'),activeTest:document.activeElement.getAttribute('data-test'),body:document.querySelector('[data-test=draft-body]')?.value,calls:{...window.keysCalls}})");
 results.draftEscape={before:await draft()};await key('Escape');results.draftEscape.after=await draft();
 await js('window.mountKeysProbe(false)');await tick();await resize(1280,480);
 await js("(async()=>{const f=window.keysFake;const s=await f.listConversations();await f.setArchived({conversation:s.conversations[0].ref,archived:true,requestId:'scroll-probe-archive'});await f.controls.flush();})()");await tick();
 results.scrollBefore=await js("(()=>{const list=document.querySelector('.inbox-scroll'),row=document.querySelectorAll('.inbox-row')[12];row.focus();list.scrollTop=170;const r=row.getBoundingClientRect();return{id:row.getAttribute('data-test'),scrollTop:list.scrollTop,rowTop:r.top,rowBottom:r.bottom,viewportHeight:innerHeight};})()");await tick();
 await click('[data-test="'+results.scrollBefore.id+'"]');await click('[data-test="rail-activity"]');await click('[data-test^="activity-open-"]');await key('Escape');
 const afterScroll=()=>js(`(()=>{const list=document.querySelector('.inbox-scroll'),row=document.querySelector('[data-test="${results.scrollBefore.id}"]'),r=row.getBoundingClientRect();return{scrollTop:list.scrollTop,rowTop:r.top,rowBottom:r.bottom,viewportHeight:innerHeight,activeTest:document.activeElement.getAttribute('data-test'),focusedRow:document.querySelector('.inbox-row.focused')?.getAttribute('data-test'),drawer:!!document.querySelector('[data-test=utility-drawer]')};})()`);
 results.scrollAfterBack=await afterScroll();await click('[data-test="drawer-close"]');results.scrollAfterDrawerClose=await afterScroll();
 writeFileSync(base+'/keyboard-scroll-probes.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results,null,2));
}finally{ws.close();}

