/* Compact conversation list: ~36px scanning rhythm, single-line rows. */
.inbox-scroll {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  height: 100%;
  min-height: 0;
}

/*
 * Flex (not grid) so the bounded trailing region cannot starve the subject:
 * when the metadata is widest (unknown read state + pending + all actions),
 * the deficit comes out of the sender column first; the subject/snippet
 * column keeps its readable floor and the metadata keeps its full content.
 */
.inbox-row {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  padding: 0.3rem 0.6rem;
  min-height: 36px;
  border-bottom: 1px solid var(--divider);
  cursor: pointer;
  /* Anchors the row action disclosure panel (meta-compact) to the row. */
  position: relative;
}

.inbox-row:focus {
  outline: none;
}

.inbox-row.focused {
  background: var(--focus-fill);
  box-shadow: inset 3px 0 0 var(--focus-accent);
}

/* Hover never changes focus or read state; it is decoration only. */
.inbox-row:not(.focused):hover {
  background: rgba(255, 255, 255, 0.03);
}

.row-sender {
  flex: 0 1 160px;
  min-width: 90px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-sender.unread {
  color: var(--text-primary);
}

.row-subject-snippet {
  flex: 1 1 136px;
  min-width: 136px; /* readable-subject floor: never collapses to zero */
  display: flex;
  gap: 0.5rem;
  white-space: nowrap;
}

.row-subject {
  flex: 0 1 auto;
  min-width: 6.5rem; /* subject keeps a readable prefix even in the widest metadata case */
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-preview {
  flex: 1 1 40%; /* preview yields to the subject; it claims at most 40% first */
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--text-secondary);
  font-size: 0.8rem;
}

.row-meta {
  flex: 0 0 auto; /* content-sized and never squeezed: no clipped actions */
  display: flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
  font-size: 0.72rem;
  color: var(--text-secondary);
}

/* Compact row action chips: tighter inline padding keeps the metadata region
   small enough that the subject column survives the 1000px contact layout. */
.row-meta button {
  padding-inline: 0.25rem;
}

/*
 * Adaptive compact action disclosure (larger-text P1): when the full inline
 * metadata does not fit the laid-out row, InboxList moves the row into the
 * `meta-compact` state. The action buttons leave the flow — kept measurable
 * (absolute, hidden, max-content) so the component can restore them exactly
 * when space returns — and the visible disclosure control keeps every action
 * named and operable. Read state, pending, and date never leave the row.
 */
.row-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.row-actions-toggle {
  display: none;
}

.inbox-row.meta-compact .row-actions-toggle {
  display: inline-flex;
}

.inbox-row.meta-compact .row-actions {
  /* Right-anchored so the hidden panel adds no rightward scrollable overflow. */
  position: absolute;
  top: calc(100% - 1px);
  right: 0.6rem;
  z-index: 6;
  visibility: hidden;
  width: max-content;
  pointer-events: none;
}

.inbox-row.meta-compact.actions-open .row-actions {
  visibility: visible;
  pointer-events: auto;
  width: auto;
  flex-direction: column;
  align-items: stretch;
  gap: 0.25rem;
  padding: 0.3rem;
  background: var(--surface-raised);
  border: 1px solid var(--divider);
  border-radius: 6px;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

/* Near the list bottom the panel opens upward to stay inside the scroller. */
.inbox-row.meta-compact.actions-open.actions-up .row-actions {
  top: auto;
  bottom: calc(100% - 1px);
}

.row-time {
  min-width: 3.5rem;
  text-align: right;
}

.row-pending {
  font-style: italic;
  color: var(--warning);
}

.row-read-state {
  font-size: 0.7rem;
}

.row-read-state[data-test='row-unread'] {
  color: var(--text-primary);
  font-weight: 600;
}

.row-group {
  padding: 0.5rem 0.6rem 0.15rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--divider);
  background: var(--surface);
}

/* Reader. */
.reader-pane,
.reader {
  min-height: 0;
  min-width: 0;
}

.reader-pane {
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
}

.reader:focus {
  outline: none;
}

.reader-toolbar {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
  flex-wrap: wrap;
}

.reader-subject {
  font-size: 1.1rem;
  overflow-wrap: anywhere;
}

.reader-pending {
  font-style: italic;
}

.messages {
  list-style: none;
  padding: 0;
  margin: 0;
}

.message {
  border-top: 1px solid var(--divider);
  padding-top: 0.5rem;
  margin-bottom: 1rem;
}

.message-header {
  display: flex;
  gap: 0.75rem;
  font-size: 0.8rem;
  margin-bottom: 0.25rem;
  flex-wrap: wrap;
  color: var(--text-secondary);
}

