    if (detailDelayMs > 0) {
      const ms = detailDelayMs;
      delayedDetailCount -= 1;
      if (delayedDetailCount <= 0) detailDelayMs = 0;
      return new Promise<T>((resolve) => { setTimeout(() => resolve(value), ms); });
